INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('git-o-github', 'Git ও GitHub: আদি থেকে অন্ত', 'Git ও GitHub: আদি থেকে অন্ত', 'প্রথম commit থেকে team-এ কাজ পর্যন্ত — বাংলায় Git ও GitHub-এর পূর্ণ বই। ৭ পর্ব, ২৯ অধ্যায়ে commit, branch, merge, conflict, rebase, ভুল শোধরানো, Pull Request, code review, GitHub Actions আর VPS-এ auto-deploy।', 820, 93, '/media/products/covers/Git_%E0%A6%93_GitHub__%E0%A6%86%E0%A6%A6_%E0%A6%A5%E0%A6%95_%E0%A6%85%E0%A6%A8%E0%A6%A4.jpg', 'Ebook', '', 1);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('jadur-shohor-js', 'জাদুর শহর JS', 'জাদুর শহর JS', 'JavaScript-কে একটা শহর হিসেবে শেখা — variable মানে বাক্স, function মানে মন্ত্র, event loop মানে ঘড়িঘর। ১০ পর্ব, ৪৬ অধ্যায়ে শুরু থেকে অ্যাডভান্সড পর্যন্ত, শেষে jQuery, HTMX, Vue, React, Angular-এর একে ঝলক আর ৪টা হাতেকলমে প্রজেক্ট।', 850, 98, '/media/products/covers/js_thumb.jpg', 'Ebook', '', 1);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('c-er-sea', 'C এর Sea', 'C এর Sea', 'সি থেকে সি++ হয়ে সি#— নদী থেকে মোহনা, মোহনা থেকে সমুদ্র রূপকে একই বইয়ে। প্রতিটা অধ্যায় শুরু হয় একটা ভাঙা প্রোগ্রাম দিয়ে যা সত্যিই কম্পাইল করে চালানো, ভুল উত্তর সহ — তারপর কেন তা খুঁজে বার করা। পয়েন্টার-মেমরি থেকে ক্লাস-টেমপ্লেট হয়ে C#-এর পরিচিতি পর্যন্ত, ১০ পর্ব ৩৮ অধ্যায়ে হাতেকলমে।', 750, 99, '/media/products/covers/c_er_sea_thumb.jpg', 'Ebook', '', 1);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('database-gochano', 'ডেটাবেজ গোছানো', 'ডেটাবেজ গোছানো', 'ঘর গোছানোর মতো করে ডেটাবেজ ডিজাইন শেখার বাংলা বই — টেবিল, সম্পর্ক, নরমালাইজেশন, SQL, ইনডেক্স ও ট্রানজেকশন হয়ে NoSQL কখন সত্যিই লাগে, ২৬৬ পৃষ্ঠায়।', 790, 111, '/media/products/covers/database_ebook_image.jpg', 'Ebook', '', 1);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('nijer-ai-agent-hatekolome', 'নিজের AI Agent হাতে-কলমে', 'নিজের AI Agent হাতে-কলমে', 'শূন্য টাকায়, একদম শুরু থেকে নিজের AI Agent বানানোর হাতে-কলমে বাংলা গাইড — Groq-এর ফ্রি API আর নিজের কম্পিউটারের Ollama দিয়ে।', 480, 480, '/media/products/covers/image_ai_agent.jpg', 'Ebook', '', 1);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('linuke-posh-manano', 'লিনুকে পোষ মানানো', 'লিনুকে পোষ মানানো', 'হাতেকলমে Linux — গল্পের ছলে &quot;লিনু&quot; নামের এক কালো বিড়ালকে পোষ মানাতে মানাতেই Linux শিখে ফেলো। WSL2/install থেকে শুরু করে filesystem, package, Bash script, cron, SSH হয়ে cloud deployment পর্যন্ত, একদম শূন্য থেকে।', 460, 94, '/media/products/covers/linux_thumb.png', 'Ebook', '', 0);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('journey-by-python', 'Journey by Python', 'Journey by Python', 'যেকোনো বয়সে একদম শূন্য থেকে Python — গল্পের ছলে Python Express-এ চড়ে basics শিখে ১০টি ভুবন (Automation, Web, Data, AI, আরও) ঘুরে দেখো, আর ঠিক করো তোমার লাইন কোনটা।', 499, 99, '/media/products/covers/jbp_thumb_L1e2QE6.png', 'Ebook', '', 0);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('ai-ml-engineer-guideline-bangla', 'AI &amp; ML Engineer হওয়ার সম্পূর্ণ গাইডলাইন', 'AI &amp; ML Engineer হওয়ার সম্পূর্ণ গাইডলাইন', 'CS/EEE শিক্ষার্থী ও self-taught developer-দের জন্য একটি সাজানো, dependency-aware ক্যারিয়ার রোডম্যাপ — শূন্য থেকে job-ready পর্যন্ত।', 0, 0, '/media/products/covers/ai-ml-thumb.png', 'Ebook', '', 0);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('context-engineering-hatekolome', 'কন্টেক্সট ইঞ্জিনিয়ারিং হাতে-কলমে', 'কন্টেক্সট ইঞ্জিনিয়ারিং হাতে-কলমে', 'CS শিক্ষার্থী ও জুনিয়র ডেভেলপারদের জন্য একটি বাস্তবমুখী গাইড — দুটি বাস্তব প্রজেক্ট দিয়ে context engineering শিখুন।', 599, 599, '/media/products/covers/file_00000000372c71fa98ee54fddeb68906.png', 'Ebook', '', 0);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('ai-debugging-prompt-pack', 'AI Debugging Prompt Pack', 'AI Debugging Prompt Pack', 'AI-কে শুধু &quot;ফিক্স করো&quot; না বলে একবারেই ঠিক সমাধান পাওয়ার রেডি প্রম্পট — মূল debug prompt, ফলো-আপ, error বোঝা আর রান করার আগেই bug খোঁজা। ChatGPT, Gemini, Claude সবখানে চলে। ৬ পাতার ফ্রি PDF, সহজ বাংলায়।', 0, 0, '/media/products/covers/ai-debugging-prompt-pack-cover.png', 'Ebook', '', 0);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('git-github-cheat-sheet', 'Git ও GitHub চিট শিট', 'Git ও GitHub চিট শিট', 'প্রতিদিনের ১০০-র বেশি Git ও GitHub command, ভুল শোধরানোর ছক আর সাধারণ error-এর সমাধান — এক জায়গায়, সহজ বাংলায়। প্রিন্ট করে ডেস্কের পাশে রাখার মতো ৬ পাতার ফ্রি চিট শিট।', 0, 0, '/media/products/covers/Git_%E0%A6%93_GitHub_%E0%A6%9A%E0%A6%9F_%E0%A6%B6%E0%A6%9F__%E0%A6%AC%E0%A6%B2%E0%A6%AF_%E0%A6%B8%E0%A6%B9%E0%A6%9C_%E0%A6%97%E0%A6%87%E0%A6%A1.jpg', 'Ebook', '', 0);
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, discounted_price, cover_image, category, badge, is_featured) VALUES ('dakghore-algorithm', 'ডাকঘরে Algorithm', 'ডাকঘরে Algorithm', 'চিঠির বস্তা থেকে প্রোগ্রামিংয়ের চিন্তা — একটা ডাকঘরের গল্পে ১৩ অধ্যায়ে algorithm। Search, sort, recursion, hashing, graph, greedy, DP — সব pseudocode-এ, trace table সহ, যেকোনো ভাষায় কাজে লাগে।', 200, 29, '/media/products/covers/dak_algo.jpg', 'Ebook', '', 0);

